using DSWI_T1_1.Dtos;using DSWI_T1_1.Models;using DSWI_T1_1.Repositories.Interfaces;using DSWI_T1_1.Services.Interfaces;namespace DSWI_T1_1.Services.Implementations;public class PacienteService:IPacienteService{private readonly IPacienteRepository r;public PacienteService(IPacienteRepository x)=>r=x;public async Task<IReadOnlyList<PacienteDto>> ObtenerTodosAsync()=>(await r.ObtenerTodosAsync()).Select(Map).ToList();public async Task<PacienteDto?> ObtenerPorIdAsync(int id){var p=await r.ObtenerPorIdAsync(id);return p==null?null:Map(p);}public Task<int> CrearAsync(PacienteDto d)=>r.CrearAsync(new Paciente{Nombre=d.Nombre.Trim(),DNI=d.DNI.Trim()});public async Task<bool> EditarAsync(PacienteDto d){if(await r.ObtenerPorIdAsync(d.PacienteID)==null)return false;return await r.EditarAsync(new Paciente{PacienteID=d.PacienteID,Nombre=d.Nombre.Trim(),DNI=d.DNI.Trim()});}private static PacienteDto Map(Paciente p)=>new(){PacienteID=p.PacienteID,Nombre=p.Nombre??"",DNI=p.DNI??""};}